using System;

namespace StdbModule;

public static partial class ItalianQuotes
{
    public static class EdmondoDeAmicis
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://it.wikiquote.org/wiki/Edmondo_De_Amicis", Text = "Eccomi preso daccapo a quest'immensa rete dorata, in cui ogni tanto bisogna cascare, volere o non volere.", Author = "Edmondo De Amicis" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Edmondo_De_Amicis", Text = "Il destino di molti uomini dipese dall'esserci o non esserci stata una biblioteca nella loro casa paterna.", Author = "Edmondo De Amicis" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Edmondo_De_Amicis", Text = "L'arte di comandare a sé stessi consiste in gran parte nel trovar argomenti e parole efficaci per movere in noi la vergogna. Ci vuol immaginazione ed eloquenza.", Author = "Edmondo De Amicis" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Edmondo_De_Amicis", Text = "La lingua spagnola, appunto perché molto più affine alla nostra che la francese, è assai più difficile a parlarsi presto, e per così dire a orecchio, senza dir degli spropositi.", Author = "Edmondo De Amicis" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Edmondo_De_Amicis", Text = "Nel cuore delle donne non ci vede chiaro che l'esaminatore disinteressato.", Author = "Edmondo De Amicis" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Edmondo_De_Amicis", Text = "Non sempre il tempo la beltà cancella | o la sfioran le lacrime e gli affanni; | mia madre ha sessant'anni, | e più la guardo e più mi sembra bella.", Author = "Edmondo De Amicis" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Edmondo_De_Amicis", Text = "Una casa senza libreria è una casa senza dignità, — ha qualcosa della locanda, — è come una città senza librai, — un villaggio senza scuole, — una lettera senza ortografia.", Author = "Edmondo De Amicis" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Edmondo_De_Amicis", Text = "Una ragazza è sempre un mistero; non c'è che fidarsi al suo viso e all'ispirazione del proprio cuore.", Author = "Edmondo De Amicis" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Edmondo_De_Amicis", Text = "L'assassino che rispetta sua madre ha ancora qualcosa di onesto e di gentile nel cuore; il piú glorioso degli uomini, che l'addolori e l'offenda, non è che una vile creatura.", Author = "Edmondo De Amicis" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Edmondo_De_Amicis", Text = "Chi rispetta la bandiera da piccolo la saprà difender da grande.", Author = "Edmondo De Amicis" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Edmondo_De_Amicis", Text = "Dare la vita per il proprio paese, come il ragazzo lombardo protagonista del racconto mensile \"La piccola vedetta lombarda\", è una grande virtú.", Author = "Edmondo De Amicis" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Edmondo_De_Amicis", Text = "Rispetta la strada. L'educazione d'un popolo si giudica innanzi tutto dal contegno ch'egli tien per la strada. Dove troverai la villania per le strade, troverai la villania nelle case.", Author = "Edmondo De Amicis" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Edmondo_De_Amicis", Text = "Pare che li faccia tutti eguali e tutti amici la scuola.", Author = "Edmondo De Amicis" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Edmondo_De_Amicis", Text = "L'uomo che pratica una sola classe sociale, è come lo studioso che non legge altro che un libro.", Author = "Edmondo De Amicis" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Edmondo_De_Amicis", Text = "La scuola è una madre.", Author = "Edmondo De Amicis" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Edmondo_De_Amicis", Text = "Immagina pure che ti siano destinati nella vita molti giorni terribili; il più terribile di tutti sarà il giorno in cui perderai tua madre.", Author = "Edmondo De Amicis" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Edmondo_De_Amicis", Text = "Pochi uomini stavan rivolti verso il mare; i più passavan a rassegna le passeggiere.", Author = "Edmondo De Amicis" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Edmondo_De_Amicis", Text = "Non aveva un ingegno di vasta organatura; ma nell'officina della sua mente, piena di minuti strumenti ben temprati e precisi, faceva bene e alla lesta un lavorìo vario e utile.", Author = "Edmondo De Amicis" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Edmondo_De_Amicis", Text = "In letteratura il suo sentimento dominante era l'odio della retorica: non credo che ci sia mai stato al mondo uomo più difficile a prendere all'amo delle belle frasi.", Author = "Edmondo De Amicis" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Edmondo_De_Amicis", Text = "A udirla parlare, pareva di vederla ringiovanire: aveva una grande semplicità, certe uscite ingenue, dei gesti scattanti di bambina.", Author = "Edmondo De Amicis" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Edmondo_De_Amicis", Text = "Lo intesi la prima volta nel «Trovatore», nel Teatro Colón di Buenos Aires, dove cantava ogni inverno da vari anni ed era, come si dice in linguaggio teatrale, l'idolo del pubblico.", Author = "Edmondo De Amicis" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Edmondo_De_Amicis", Text = "Non ci fu mai cantante celebre più prodigo di lui della propria voce.", Author = "Edmondo De Amicis" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Edmondo_De_Amicis", Text = "La condizione di moglie del Verdi, somigliante per certi rispetti a quella del marito non regnante d'una regina, non era facile.", Author = "Edmondo De Amicis" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Edmondo_De_Amicis", Text = "Pittore di donne, forse, meglio che d'uomini, e pittore impareggiabile di famiglie – mamme, signorine, ragazzi, bambini – stupendamente raggruppati e atteggiati.", Author = "Edmondo De Amicis" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Edmondo_De_Amicis", Text = "O divina Sicilia! Quanti Italiani, che hanno corso il mondo per diletto, morirono o moriranno senza averti veduta!", Author = "Edmondo De Amicis" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Edmondo_De_Amicis", Text = "Quale delle città decadute, o scomparse, del mondo antico ha conservato, dopo Atene e Roma, una così vasta fama come Siracusa?", Author = "Edmondo De Amicis" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Edmondo_De_Amicis", Text = "Tramontava il sole: l'orizzonte era d'oro, le acque dei ponti d'oro, tutto quanto s'alzava sopra la terra e sorgeva dal mare disegnava le sue forme nell'oro.", Author = "Edmondo De Amicis" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Edmondo_De_Amicis", Text = "Siracusa vista da questa terrazza sembra galleggiare, come se dormisse, sognando i sui duemila e settecento anni di storia.", Author = "Edmondo De Amicis" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Edmondo_De_Amicis", Text = "Ti ringrazio della bella lettera, la quale, dopo tanti mesi di silenzio, m'è stata cagione di vivissimo piacere.", Author = "Edmondo De Amicis" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Edmondo_De_Amicis", Text = "L'emozione che provai entrando in Costantinopoli mi fece quasi dimenticare tutto quello che vidi in dieci giorni di navigazione dallo stretto di Messina all'imboccatura del Bosforo.", Author = "Edmondo De Amicis" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Edmondo_De_Amicis", Text = "Povero martire! Ogni volta che entrai nella sua bottega, ci risi molto; ma ne uscii pieno d'ammirazione e di pietà.", Author = "Edmondo De Amicis" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Edmondo_De_Amicis", Text = "Era il primo di gennaio del 1896. Salii la mattina sul tranvai per il corso Vinzaglio, in via Roma.", Author = "Edmondo De Amicis" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Edmondo_De_Amicis", Text = "Mi domanderete per prima cosa: Voi, per quistione sociale, che cosa intendete?", Author = "Edmondo De Amicis" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Edmondo_De_Amicis", Text = "Era una bella giornata d'agosto; non una nuvola, non un soffio di vento; l'aria immobile e infocata.", Author = "Edmondo De Amicis" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Edmondo_De_Amicis", Text = "Lo stretto di Gibilterra è forse di tutti gli stretti quello che separa più nettamente due paesi più diversi, e questa diversità appare anche maggiore andando a Tangeri da Gibilterra.", Author = "Edmondo De Amicis" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Edmondo_De_Amicis", Text = "Chi guarda per la prima volta una grande carta dell'Olanda, si meraviglia che un paese così fatto possa esistere.", Author = "Edmondo De Amicis" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Edmondo_De_Amicis", Text = "Pioveva, il mare era agitato, il bastimento ballava come una barchetta; a una mezz'ora appena da Dieppe provai, per la prima volta in vita mia, i sintomi del mal di mare.", Author = "Edmondo De Amicis" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Edmondo_De_Amicis", Text = "Eccomi preso daccapo a quest'immensa rete dorata, in cui ogni tanto bisogna cascare, volere o non volere.", Author = "Edmondo De Amicis" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Edmondo_De_Amicis", Text = "Era una mattina piovosa di febbraio, e mancava un'ora al levar del sole.", Author = "Edmondo De Amicis" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Edmondo_De_Amicis", Text = "Un Piemontese, che deve andare a Roma tra poco, sentì il bisogno, qualche giorno fa, di mandar un saluto alla città di Firenze, e pensò di mandarglielo dalla cima della collina di Fiesole.", Author = "Edmondo De Amicis" },
        };
    }
}